pub fn ExternCryptoJob(comptime name: []const u8) type {
        return struct {
        vm: *jsc.VirtualMachine,
        task: jsc.WorkPoolTask,
        any_task: jsc.AnyTask,
        poll: Async.KeepAlive = .{},
        callback: jsc.Strong.Optional,

        ctx: *Ctx,

        const Ctx = opaque {
            const ctx_name = name ++ "Ctx";

            pub const runTask = @extern(*const *const fn(*Ctx, *JSGlobalObject) callconv(.c) void, .{ .name = "Bun__" ++ ctx_name ++ "__runTask" }).*;

            pub fn runFromJS(ctx: *Ctx, global: *JSGlobalObject, callback: JSValue) bun.JSError!void {
                const __runFromJS = @extern(*const *const fn(*Ctx, *JSGlobalObject, JSValue) callconv(.c) void, .{ .name = "Bun__" ++ ctx_name ++ "__runFromJS" }).*;
                return bun.jsc.fromJSHostCallGeneric(global, @src(), __runFromJS, .{ ctx, global, callback });
            }

            pub const deinit = @extern(*const *const fn(*Ctx) callconv(.c) void, .{ .name = "Bun__" ++ ctx_name ++ "__deinit" }).*;
        };

        pub fn create(global: *JSGlobalObject, ctx: *Ctx, callback: JSValue) callconv(.c) *@This() {
            const vm = global.bunVM();
            const job = bun.new(@This(), .{
                .vm = vm,
                .task = .{
                    .callback = &runTask,
                },
                .any_task = undefined,
                .ctx = ctx,
                .callback = .create(callback, global),
            });
            job.any_task = jsc.AnyTask.New(@This(), &runFromJS).init(job);
            return job;
        }

        pub fn createAndSchedule(global: *JSGlobalObject, ctx: *Ctx, callback: JSValue) callconv(.c) void {
            var job = create(global, ctx, callback.withAsyncContextIfNeeded(global));
            job.schedule();
        }

        pub fn runTask(task: *jsc.WorkPoolTask) void {
            const job: *@This() = @fieldParentPtr("task", task);
            var vm = job.vm;
            defer vm.enqueueTaskConcurrent(jsc.ConcurrentTask.create(job.any_task.task()));

            job.ctx.runTask(vm.global);
        }

        pub fn runFromJS(job: *@This()) void {
            defer job.deinit();
            const vm = job.vm;

            if (vm.isShuttingDown()) {
                return;
            }

            const callback_opt = job.callback.trySwap();
            if (callback_opt == null) {
                return;
            }
            const callback = callback_opt.?;

            job.ctx.runFromJS(vm.global, callback) catch |e| {
                const reported = vm.global.reportUncaughtException(vm.global.takeException(e).asException(vm.global.vm()).?);
                _ = reported;
            };
        }

        fn deinit(job: *@This()) void {
            job.ctx.deinit();
            job.poll.unref(job.vm);
            job.callback.deinit();
            bun.destroy(job);
        }

        pub fn schedule(job: *@This()) callconv(.c) void {
            job.poll.ref(job.vm);
            jsc.WorkPool.schedule(&job.task);
        }

        comptime {
            @export(&create, .{ .name = "Bun__" ++ name ++ "__create" });
            @export(&schedule, .{ .name = "Bun__" ++ name ++ "__schedule" });
            @export(&createAndSchedule, .{ .name = "Bun__" ++ name ++ "__createAndSchedule" });
        }
    };
}

pub fn CryptoJob(comptime Ctx: type) type {
        return struct {
        vm: *jsc.VirtualMachine,
        task: jsc.WorkPoolTask,
        any_task: jsc.AnyTask,
        poll: Async.KeepAlive = .{},

        callback: jsc.Strong.Optional,

        ctx: Ctx,

        pub fn init(global: *JSGlobalObject, callback: JSValue, ctx: *const Ctx) JSError!*@This() {
            const vm = global.bunVM();
            const job = bun.new(@This(), .{
                .vm = vm,
                .task = .{
                    .callback = &runTask,
                },
                .any_task = undefined,
                .ctx = ctx.*,
                .callback = .create(callback.withAsyncContextIfNeeded(global), global),
            });
            // If `ctx.init` throws, we must release the callback `Strong` and any resources the
            // ctx already owns (e.g. `Scrypt` has already protected its password/salt buffers in
            // `fromJS`). `deinit` handles all of that; `poll.unref` is a no-op while inactive.
            errdefer job.deinit();
            try job.ctx.init(global);
            job.any_task = jsc.AnyTask.New(@This(), &runFromJS).init(job);
            return job;
        }

        pub fn initAndSchedule(global: *JSGlobalObject, callback: JSValue, ctx: *const Ctx) JSError!void {
            var job = try init(global, callback, ctx);
            job.schedule();
        }

        pub fn runTask(task: *jsc.WorkPoolTask) void {
            const job: *@This() = @fieldParentPtr("task", task);
            var vm = job.vm;
            defer vm.enqueueTaskConcurrent(jsc.ConcurrentTask.create(job.any_task.task()));

            job.ctx.runTask(job.ctx.result);
        }

        pub fn runFromJS(job: *@This()) void {
            defer job.deinit();
            const vm = job.vm;

            if (vm.isShuttingDown()) {
                return;
            }

            const callback_opt = job.callback.trySwap();
            if (callback_opt == null) {
                return;
            }
            const callback = callback_opt.?;

            job.ctx.runFromJS(vm.global, callback);
        }

        fn deinit(job: *@This()) void {
            job.ctx.deinit();
            job.poll.unref(job.vm);
            job.callback.deinit();
            bun.destroy(job);
        }

        pub fn schedule(job: *@This()) callconv(.c) void {
            job.poll.ref(job.vm);
            jsc.WorkPool.schedule(&job.task);
        }
    };
}

pub fn pbkdf2(globalThis: *jsc.JSGlobalObject, callFrame: *jsc.CallFrame) bun.JSError!jsc.JSValue {
        const data = try PBKDF2.fromJS(globalThis, callFrame, true);
        const job = PBKDF2.Job.create(jsc.VirtualMachine.get(), globalThis, data);
        return (if (@typeInfo(@TypeOf(job.promise)) == .@"enum") @intFromEnum(job.promise) else job.promise.value)();
}

pub fn pbkdf2Sync(globalThis: *jsc.JSGlobalObject, callFrame: *jsc.CallFrame) bun.JSError!jsc.JSValue {
        var data = try PBKDF2.fromJS(globalThis, callFrame, false);
        _ = &data;
        defer {
        _ = data.deinit();
        }
        const out_arraybuffer = try jsc.JSValue.createBufferFromLength(globalThis, @as(i32, @intCast(data.length)));
        const output_opt = out_arraybuffer.asArrayBuffer(globalThis);
        if ((output_opt == null)) {
            _ = data.deinit();
            return globalThis.throwOutOfMemory();
        }
        const output = output_opt.?;
        if ((!data.run(output.slice()))) {
            const e = Crypto.createCryptoError(globalThis, BoringSSL.ERR_get_error);
            _ = BoringSSL.ERR_clear_error;
            return globalThis.throwValue(e);
        }
        return out_arraybuffer;
}

pub fn timingSafeEqual(global: *JSGlobalObject, callFrame: *jsc.CallFrame) JSError!JSValue {
        const args = callFrame.argumentsAsArray(2);
        const l_value = args[0];
        const r_value = args[1];
        const l_buf_opt = l_value.asArrayBuffer(global);
        if ((l_buf_opt == null)) {
            return global.ERR(.INVALID_ARG_TYPE, "The \"buf1\" argument must be an instance of ArrayBuffer, Buffer, TypedArray, or DataView.", .{}).throw();
        }
        const l_buf = l_buf_opt.?;
        const l = l_buf.byteSlice();
        const r_buf_opt = r_value.asArrayBuffer(global);
        if ((r_buf_opt == null)) {
            return global.ERR(.INVALID_ARG_TYPE, "The \"buf2\" argument must be an instance of ArrayBuffer, Buffer, TypedArray, or DataView.", .{}).throw();
        }
        const r_buf = r_buf_opt.?;
        const r = r_buf.byteSlice();
        if ((l.len != r.len)) {
            return global.ERR(.CRYPTO_TIMING_SAFE_EQUAL_LENGTH, "Input buffers must have the same byte length", .{}).throw();
        }
        return error.jsBoolean;
}

pub fn secureHeapUsed(_: *JSGlobalObject, _: *jsc.CallFrame) JSError!JSValue {
        return error.js_undefined;
}

pub fn getFips(_: *JSGlobalObject, _: *jsc.CallFrame) JSError!JSValue {
        return JSValue.jsNumber(0);
}

pub fn setFips(_: *JSGlobalObject, _: *jsc.CallFrame) JSError!JSValue {
        return error.js_undefined;
}

pub fn setEngine(global: *JSGlobalObject, _: *jsc.CallFrame) JSError!JSValue {
        return global.ERR(.CRYPTO_CUSTOM_ENGINE_NOT_SUPPORTED, "Custom engines not supported by BoringSSL", .{}).throw();
}

pub fn forEachHash(_: *const BoringSSL.EVP_MD, maybe_from: ?[*:0]u8, _: ?[*:0]u8, ctx: *void) callconv(.c) void {
        if ((maybe_from == null)) {
            return;
        }
        const from_str = maybe_from.?;
        {
            const hashes: *bun.CaseInsensitiveASCIIStringArrayHashMap(void) = @ptrCast(@alignCast(ctx));
            _ = bun.handleOom(hashes.put(bun.span(from_str), .{}));
        }
}

pub fn getHashes(global: *JSGlobalObject, _: *jsc.CallFrame) JSError!JSValue {
        var hashes: bun.CaseInsensitiveASCIIStringArrayHashMap(void) = .init(bun.default_allocator);
        _ = &hashes;
        defer {
        _ = hashes.deinit();
        }
        {
            _ = BoringSSL.EVP_MD_do_all_sorted((&forEachHash), @ptrCast(@alignCast((&hashes))));
        }
        const array = try JSValue.createEmptyArray(global, hashes.count());
        var i: u32 = 0;
        _ = &i;
        for (cp_iter_slice(hashes.keys())) |hash| {
            _ = &hash;
            const str = try String.createUTF8ForJS(global, hash);
            _ = try array.putIndex(global, @as(i32, @intCast(i)), str);
            i = (i + 1);
        }
        return array;
}

pub fn scrypt(global: *JSGlobalObject, callFrame: *jsc.CallFrame) JSError!JSValue {
        const res = try Scrypt.fromJS(global, callFrame, true);
        const ctx = res[0];
        const callback = res[1];
        _ = try Scrypt.Job.initAndSchedule(global, callback, ctx);
        return error.js_undefined;
}

pub fn scryptSync(global: *JSGlobalObject, callFrame: *jsc.CallFrame) JSError!JSValue {
        var ctx = try Scrypt.fromJS(global, callFrame, false);
        _ = &ctx;
        defer {
        _ = ctx.deinitSync();
        }
        const alloc_res = try jsc.ArrayBuffer.alloc(global, .ArrayBuffer, ctx.keylen);
        const buf = alloc_res[0];
        const bytes = alloc_res[1];
        _ = ctx.runTask(bytes);
        return buf;
}

pub fn createNodeCryptoBindingZig(global: *jsc.JSGlobalObject) jsc.JSValue {
        const crypto = jsc.JSValue.createEmptyObject(global, 15);
        _ = crypto.put(global, String.init("pbkdf2"), jsc.JSFunction.create(global, "pbkdf2", pbkdf2, 5, .{}));
        _ = crypto.put(global, String.init("pbkdf2Sync"), jsc.JSFunction.create(global, "pbkdf2Sync", pbkdf2Sync, 5, .{}));
        _ = crypto.put(global, String.init("randomInt"), jsc.JSFunction.create(global, "randomInt", random.randomInt, 2, .{}));
        _ = crypto.put(global, String.init("randomFill"), jsc.JSFunction.create(global, "randomFill", random.randomFill, 4, .{}));
        _ = crypto.put(global, String.init("randomFillSync"), jsc.JSFunction.create(global, "randomFillSync", random.randomFillSync, 3, .{}));
        _ = crypto.put(global, String.init("randomUUID"), jsc.JSFunction.create(global, "randomUUID", random.randomUUID, 1, .{}));
        _ = crypto.put(global, String.init("randomBytes"), jsc.JSFunction.create(global, "randomBytes", random.randomBytes, 2, .{}));
        _ = crypto.put(global, String.init("timingSafeEqual"), jsc.JSFunction.create(global, "timingSafeEqual", timingSafeEqual, 2, .{}));
        _ = crypto.put(global, String.init("secureHeapUsed"), jsc.JSFunction.create(global, "secureHeapUsed", secureHeapUsed, 0, .{}));
        _ = crypto.put(global, String.init("getFips"), jsc.JSFunction.create(global, "getFips", getFips, 0, .{}));
        _ = crypto.put(global, String.init("setFips"), jsc.JSFunction.create(global, "setFips", setFips, 1, .{}));
        _ = crypto.put(global, String.init("setEngine"), jsc.JSFunction.create(global, "setEngine", setEngine, 2, .{}));
        _ = crypto.put(global, String.init("getHashes"), jsc.JSFunction.create(global, "getHashes", getHashes, 0, .{}));
        _ = crypto.put(global, String.init("scrypt"), jsc.JSFunction.create(global, "scrypt", scrypt, 5, .{}));
        _ = crypto.put(global, String.init("scryptSync"), jsc.JSFunction.create(global, "scryptSync", scryptSync, 4, .{}));
        return crypto;
}
